        return new List<EquipmentItem>
        {
            new(1, "Forklift A",        "Warehouse 1",  new DateTime(2026, 5, 10)),
            new(2, "Conveyor Belt B",   "Warehouse 2",  new DateTime(2026, 4, 22)),
            new(3, "Drill Press C",     "Workshop",      new DateTime(2026, 3, 15)),
            new(4, "Lathe D",           "Workshop",      new DateTime(2026, 5, 30)),
            new(5, "Crane E",           "Yard",          new DateTime(2026, 1, 8)),
            new(6, "Compressor F",      "Warehouse 1",  new DateTime(2026, 2, 14)),
            new(7, "Welder G",          "Workshop",      new DateTime(2025, 12, 1)),
            new(8, "Generator H",       "Yard",          new DateTime(2026, 5, 25)),
        };
    }
}

@page "/inventory"
@rendermode InteractiveServer
@implements IDisposable
@inject EquipmentService EquipmentSvc
@inject PersistentComponentState ApplicationState

<PageTitle>Inventory</PageTitle>

<h1>Equipment Inventory</h1>

@if (equipment is null)
{
    <p><em>Loading inventory...</em></p>
}
else
{
    <table class="table">
        <thead>
            <tr>
                <th>Id</th>
                <th>Name</th>
                <th>Location</th>
                <th>Last Inspected</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var item in equipment)
            {
                <tr>
                    <td>@item.Id</td>
                    <td>@item.Name</td>
                    <td>@item.Location</td>
                    <td>@item.LastInspected.ToShortDateString()</td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private List<EquipmentItem>? equipment;
    private PersistingComponentStateSubscription _subscription;

    protected override async Task OnInitializedAsync()
    {
        // Register a callback so the prerender pass persists the data
        // into the HTML payload for the interactive runtime to pick up.
        _subscription = ApplicationState.RegisterOnPersisting(PersistData);

        // Try to restore data that was already fetched during prerender.
        // If found, skip the service call entirely (no double fetch).
        if (!ApplicationState.TryTakeFromJson<List<EquipmentItem>>(
                nameof(equipment), out var restored))
        {
            // First render (prerender): fetch from the service.
            restored = await EquipmentSvc.GetEquipmentAsync();
        }

        equipment = restored;
    }

    private Task PersistData()
    {
        ApplicationState.PersistAsJson(nameof(equipment), equipment);
        return Task.CompletedTask;
    }

    public void Dispose() => _subscription.Dispose();
}

